// Generates config/cues.js (a browser global) and config/mark_grid.js from the JSON sources.
// Run: node scripts/build-cues.mjs
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const cues = JSON.parse(readFileSync(join(root, "config/cues.json"), "utf8"));
const grid = JSON.parse(readFileSync(join(root, "assets/brand/mark_grid.json"), "utf8"));

writeFileSync(
  join(root, "config/cues.js"),
  "// GENERATED by scripts/build-cues.mjs from config/cues.json — edit the JSON, not this file.\n" +
    "window.HK_CUES = " + JSON.stringify(cues, null, 2) + ";\n" +
    "window.HK_MARK_GRID = " + JSON.stringify(grid) + ";\n",
);
console.log("config/cues.js written");
